    def _on_window_configure(self, event):
        """Dynamically adjusts text wrap widths and responsive layout when window is resized or DPI changes."""
        try:
            if event.widget == self.root and self._is_alive(self.root):
                curr_w = event.width
                if curr_w > 100:
                    if hasattr(self, "understood_label") and self._is_alive(self.understood_label):
                        self.understood_label.config(wraplength=max(280, curr_w - 70))
                    if hasattr(self, "subtitle_label") and self._is_alive(self.subtitle_label):
                        self.subtitle_label.config(wraplength=max(280, curr_w - 240))
        except Exception:
            pass

    def _bind_hover_fx(self, widget, normal_bg, hover_bg, normal_fg=None, hover_fg=None):
        """Binds smooth visual hover state animation to buttons, frames, and composite child widgets."""
        if not widget:
            return
        def _get_targets():
            try:
                if hasattr(widget, "winfo_children"):
                    return [widget] + list(widget.winfo_children())
            except Exception:
                pass
            return [widget]

        def _on_enter(e):
            for w in _get_targets():
                try:
                    if w.winfo_exists():
                        w.config(bg=hover_bg)
                        if hover_fg and hasattr(w, "cget") and "fg" in w.keys():
                            w.config(fg=hover_fg)
                except Exception:
                    pass

        def _on_leave(e):
            for w in _get_targets():
                try:
                    if w.winfo_exists():
                        w.config(bg=normal_bg)
                        if normal_fg and hasattr(w, "cget") and "fg" in w.keys():
                            w.config(fg=normal_fg)
                except Exception:
                    pass

        try:
            widget.bind("<Enter>", _on_enter, add="+")
            widget.bind("<Leave>", _on_leave, add="+")
            if hasattr(widget, "winfo_children"):
                for child in widget.winfo_children():
                    child.bind("<Enter>", _on_enter, add="+")
                    child.bind("<Leave>", _on_leave, add="+")
        except Exception:
            pass

    def _start_pulse_animation(self):
        """Smooth breathing glow animation on active listening badge."""
        if hasattr(self, "audio_status_badge") and self._is_alive(self.audio_status_badge):
            try:
                self._pulse_idx = (self._pulse_idx + 1) % len(self._pulse_colors)
                color = self._pulse_colors[self._pulse_idx]
                if "Listening" in self.audio_status_badge.cget("text"):
                    self.audio_status_badge.config(fg=color)
            except Exception:
                pass
        self.safe_after(450, self._start_pulse_animation)

    def _is_alive(self, widget=None) -> bool:
        """Checks if the Tkinter root and widget are alive and have not been destroyed."""
        try:
            if not hasattr(self, "root") or not self.root:
                return False
            if not self.root.winfo_exists():
                return False
            if widget is not None:
                if not hasattr(widget, "winfo_exists") or not widget.winfo_exists():
                    return False
            return True
        except Exception:
            return False

    def safe_after(self, delay_ms: int, callback: Callable):
        """Dispatches callback on Tkinter main thread safely if window/widgets are still alive."""
        if not self._is_alive():
            return
        def _safe_wrapper():
            try:
                if self._is_alive():
                    callback()
            except (tk.TclError, RuntimeError, Exception):
                pass
        try:
            self.root.after(delay_ms, _safe_wrapper)
        except (tk.TclError, RuntimeError, Exception):
            pass
        
