        diff_var = tk.StringVar(value="Senior")
        diff_cb = ttk.Combobox(ctrl_frame, textvariable=diff_var, values=["Junior", "Mid-Level", "Senior", "Staff / Principal", "FAANG"], state="readonly", width=14)
        diff_cb.pack(side="left")

